export async function renameBranch(
  oldName: string,
  newName: string,
  cwd: string,
): Promise<void> {
  try {
    await execa('git', ['branch', '-m', oldName, newName], { cwd });
  } catch (error) {
    throw new DubError(
      formatGitFailure(
        `Failed to rename branch '${oldName}' to '${newName}'.`,
        readGitCommandOutput(error),
      ),
      [...]
    );
  }
}

